// Проверяем подпись и готовим текст сообщения.
//
// Воркер мини-аппа подписывает тело события ключом N8N_WEBHOOK_SECRET и
// кладёт подпись в заголовок x-nyraflow-signature. Без проверки любой, кто
// узнает адрес вебхука, сможет слать сюда что угодно.

const crypto = require('crypto');

const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};

const secret = $env.N8N_WEBHOOK_SECRET || '';
const received = String(headers['x-nyraflow-signature'] || '');
const expected = secret
  ? crypto.createHmac('sha256', secret).update(JSON.stringify(body)).digest('hex')
  : '';

let valid = false;
if (secret && received.length === expected.length && received.length > 0) {
  valid = crypto.timingSafeEqual(Buffer.from(received), Buffer.from(expected));
}

const type = String(body.type || 'unknown');
const payload = body.payload || {};
const eventId = String(headers['x-nyraflow-event-id'] || body.id || '');

// Тексты сообщений. Правьте прямо здесь — это обычный JavaScript.
const PRODUCTS = {
  landing: 'Лендинг (от 30 000 ₽)',
  web_service: 'Веб-сервис или Mini App (от 60 000 ₽)',
  ai_automation: 'Сайт с AI-автоматизацией (от 120 000 ₽)',
};

let text = '';
let notify = true;

if (type === 'lead.created') {
  text =
    '🟢 <b>Новая заявка из мини-аппа</b>\n\n' +
    'Заявка №' + (payload.leadId || '—') + '\n' +
    (payload.intent === 'discuss' ? 'Клиент нажал «обсудить разбор»' : 'Клиент заполнил бриф');
} else if (type === 'brief.analyzed') {
  text =
    '📋 <b>Разбор брифа готов</b>\n\n' +
    'Заявка №' + (payload.leadId || '—') + '\n' +
    'Формат: ' + (PRODUCTS[payload.recommendedProduct] || payload.recommendedProduct || '—') + '\n' +
    (payload.isFallback ? '⚠️ Разбор собран шаблоном — модель была недоступна' : 'Модель: ' + (payload.model || '—'));
} else {
  // Событие известного типа, но уведомлять о нём не нужно.
  notify = false;
  text = 'Событие ' + type + ' получено и пропущено';
}

return [{ json: { valid, notify, type, eventId, text } }];
